Giữ nguyên như vậy?

{{ case Level when "None" LevelString = "Không có sóng thần" when "Forecast" LevelString = "Dự báo sóng thần" when "Advisory" LevelString = "Khuyến cáo sóng thần" when "Warning" LevelString = "Cảnh báo sóng thần" when "MajorWarning" LevelString = "Cảnh báo sóng thần lớn" else LevelString = "Thông tin sóng thần" end case PreviousLevel when "None" PreviousLevelString = "Không có sóng thần" when "Forecast" PreviousLevelString = "Dự báo sóng thần" when "Advisory" PreviousLevelString = "Khuyến cáo sóng thần" when "Warning" PreviousLevelString = "Cảnh báo sóng thần" when "MajorWarning" PreviousLevelString = "Cảnh báo sóng thần lớn" else PreviousLevelString = "Thông tin sóng thần" end
if PreviousLevel != Level if PreviousLevel == "None" LevelString + " đã được công bố." else if Level == "None" if PreviousLevel == "Forecast" "Dự báo sóng thần đã hết hạn." else PreviousLevelString + " đã được dỡ bỏ." end else PreviousLevelString + " đã chuyển sang " + LevelString + "." end end}}
